def hero(eyebrow, title, sub, chips=(), portal=False, lead=None):
    c = ''.join(f'<a class="p-chip" href="{h}" style="display: inline-flex; padding: 12px 16px; border: 1px solid rgba(255,255,255,0.35); font-size: 10px; letter-spacing: 0.16em; text-transform: uppercase; font-weight: 700; transition: border-color .2s, color .2s;">{t} {"↓︎" if h.startswith("#") else "→︎"}</a>' for t, h in chips)
    p = ''
    if lead: p = f'<a href="{lead[1]}" style="display: inline-flex; padding: 12px 16px; border: 1px solid #00ADB5; font-size: 10px; letter-spacing: 0.16em; text-transform: uppercase; font-weight: 700; background: #00ADB5; color: #000000;">{lead[0]} →︎</a>' + p
    return f'''
  <section class="p-hero" style="position: relative; min-height: 560px; padding: 200px 8vw 80px; background: #111111; box-sizing: border-box; display: flex; flex-direction: column; justify-content: flex-end;">
    <div style="{EYE} color: #00ADB5;">{eyebrow}</div>
    <h1 class="p-h1" style="font-size: 120px; line-height: 0.86; letter-spacing: -0.075em; font-weight: 800; margin: 0 0 26px; text-transform: uppercase;">{title}</h1>
    <p style="font-size: 16px; line-height: 1.7; max-width: 520px; color: #D2D8D4; margin: 0 0 28px;">{sub}</p>
    {('<div style="margin-bottom: 22px;">' + APPS + '</div>') if portal else ''}<div style="display: flex; gap: 8px; flex-wrap: wrap; align-items: center;">{p}{c}</div>
  </section>'''

def section(sid, theme, eyebrow, h2, intro, body, side=''):
    bg, fg, eyc, emc, mut, rule = THEMES[theme]
    bar = ' border-left: 3px solid #00ADB5; padding-left: 10px;' if theme in ('white', 'gray') else ''
    cls = 'h-sec' + (' p-dark' if theme == 'dark' else '') + (' p-teal' if theme == 'teal' else '')
    intro_html = f'<p style="max-width: 360px; color: {mut}; font-size: 14px; line-height: 1.7; margin: 0;">{intro}</p>' if intro else ''
    return f'''
  <section id="{sid}" class="{cls}" style="padding: 100px 8vw; background: {bg}; color: {fg};">
    <div class="h-head" style="display: flex; justify-content: space-between; align-items: flex-end; gap: 30px; margin-bottom: 40px;">
      <div>
        <div style="{EYE} color: {eyc};{bar}">{eyebrow}</div>
        <h2 style="font-size: 72px; letter-spacing: -0.065em; line-height: 0.94; margin: 0; font-weight: 700;">{h2}</h2>
      </div>
      {side or intro_html}
    </div>
    {body}
  </section>'''

def ph(text):
    return f'<div class="p-ph"><b style="letter-spacing: 0.16em; font-size: 10px; text-transform: uppercase;">Placeholder</b> · {text}</div>'

def grid(n, items, cls=None):
    cls = cls or f'p-g{n}'
    return f'<div class="{cls}" style="display: grid; grid-template-columns: repeat({n}, minmax(0, 1fr)); gap: 14px;">{"".join(items)}</div>'

def card(title, text, theme='white', photo=None, tag=None, more=None, link=None, form=None, gform=None, open_label='More details'):
    """A card with an optional 'More details' slide-over (more = list of lines; '- ' makes a bullet)
    and an optional link button (link = (label, url)). Both are off unless given."""
    bg = {'white': '#F2F2F2', 'gray': '#FFFFFF', 'dark': '#161616', 'teal': '#FFFFFF'}[theme]
    fg = '#F7F7F3' if theme == 'dark' else '#111111'
    mut = '#AEB8B3' if theme == 'dark' else '#555555'
    img = f'<div style="height: 200px; background: #1C1C1C; display: flex; align-items: center; justify-content: center; color: #888888; font-size: 10px; letter-spacing: 0.12em; text-transform: uppercase;">{photo}</div>' if photo else ''
    tg = f'<div style="font-size: 10px; letter-spacing: 0.18em; text-transform: uppercase; color: {"#00ADB5" if theme == "dark" else "#111111"}; margin-bottom: 10px;">{tag}</div>' if tag else ''
    foot = ''
    if form or gform: more = more or ['']
    if link or more:
        foot = '<div style="margin-top: auto; padding-top: 18px; display: flex; gap: 14px; align-items: center; flex-wrap: wrap;">'
        if link:
            lb, lc = ('#00ADB5', '#000000') if theme == 'dark' else ('#111111', '#FFFFFF')
            ext = link[1].startswith('http')
            foot += f'<a href="{link[1]}"' + (' target="_blank" rel="noopener"' if ext else '') + f' class="p-rcbtn" style="display: inline-block; padding: 11px 14px; background: {lb}; color: {lc}; font-size: 10px; letter-spacing: 0.16em; text-transform: uppercase; font-weight: 700;">{link[0]} ↗︎</a>'
        if more:
            q = lambda x: html.escape(html.unescape(x), quote=True)
            foot += (f'<button type="button" class="p-rcmore" onClick="{{{{openCard}}}}" data-t="{q(title)}" data-d="{q(text)}" data-more="{q("|".join(more))}"'
                     + (f' data-label="{q(link[0])}" data-url="{q(link[1])}"' if link else '') + (f' data-tag="{q(tag)}"' if tag else '') + (f' data-photo="{q(photo)}"' if photo else '') + (f' data-form="{form}"' if form else '') + (f' data-gform="{q(gform[1])}" data-gform-label="{q(gform[0])}"' if gform else '')
                     + f' style="padding: 0 0 3px; border: 0; border-bottom: 1px solid {fg}; background: none; color: {fg}; font-family: inherit; font-size: 10px; letter-spacing: 0.16em; text-transform: uppercase; font-weight: 700; cursor: pointer;">{open_label} →︎</button>')
        foot += '</div>'
