def legal(slug, title, intro, blocks, height):
    body = ''
    for kind, t in blocks:
        t = _h.escape(t)
        body += (f'<h3 style="font-size: 20px; letter-spacing: -0.02em; margin: 30px 0 10px;">{t}</h3>' if kind == 'h' else
                 f'<p style="font-size: 15px; line-height: 1.75; color: #333333; margin: 0 0 14px;">{t}</p>' if kind == 'p' else
                 f'<div style="border: 1px dashed #9A9A9A; padding: 14px 16px; margin: 0 0 22px; font-size: 13px; line-height: 1.6; color: #555555;"><b style="font-size: 10px; letter-spacing: 0.16em; text-transform: uppercase;">For review</b> · {t}</div>')
    content = hero('Legal', title, intro) + f'<section class="h-sec" style="padding: 80px 8vw; background: #FFFFFF; color: #111111;"><div style="max-width: 760px;">{body}</div></section>'
    page(slug, _h.unescape(title.replace('<br>', ' ')), content, height)
